;---------------------------------------------------------------------------------------------------
; SpeedCtlControl ($3B800)
; Called from: MainLoop
;---------------------------------------------------------------------------------------------------
SpeedCtlControl:
        AIS     #$FA
        TSY
        JSR     SpeedCtlSwitchCheck
        JSR     SpeedCtlBusCheck
        LDAB    #$00
        BRCLR   >SwitchInputs2,Z,#$10,L3B8AC             ; bit 4: speed control switch (on/off, probably)
        LDAB    #$01
        LDAA    >VehicleSpeed,Z
        CMPA    >SpeedCtlEngageSpeedMin
        LBCS    L3B8AC
        LDAB    #$02
        LDAA    >EngineRpm,Z
        CMPA    >SpeedCtlRpmMax
        BCC     L3B8AC
        LDAB    #$03
        BRSET   >SwitchInputs,Z,#$01,L3B8AC              ; bit 0: brake switch (BrakeSwitchMonitor, idle, speed damping, purge test)
        LDAB    #$0D
        BRSET   >SwitchInputs2,Z,#$01,L3B8AC             ; bit 0: speed control switch
        BRSET   >Options032E,#$40,L3B854                 ; bit 6: manual transmission: GearStateUpdate and the park/neutral monitor are skipped
        JSR     SpeedCtlBusState
        BCS     L3B8AC
        LDAB    #$04
        BRCLR   >SwitchInputs2,Z,#$20,L3B8AC             ; bit 5: park/neutral switch (gear state, starter cut, park/neutral monitor)
        BRA     L3B87C
L3B854:
        LDAB    #$05
        LDAA    >RefPeriod,Z
        BNE     L3B86C
        LDAA    >RpmSpeedRatio,Z
        CMPA    >SpeedCtlRatioMax
        BCC     L3B8AC
        CMPA    >SpeedCtlRatioMin
        BCS     L3B8AC
L3B86C:
        LDAB    #$06
        BRSET   >SpeedCtlState,Z,#$80,L3B87C             ; bit 7: speed control off: not engaged or cancelled (set at reset and on cancel)
        BRCLR   >SpeedCtlRpmJumpTimer,Z,#$FF,L3B87C
        BRA     L3B8AC
L3B87C:
        LDAB    #$07
        BRSET   >FaultSet00,Z,#$80,L3B8AC                ; bit 7: fault row $0F, no P-code
        BRSET   >SpeedCtlFlags,Z,#$02,L3B8AC             ; bit 1: switch count at 8 or more (SpeedCtlSwitchCheck)
        BRCLR   >FaultSet0B,Z,#$C0,L3B894                ; bit 7: fault row $57, no P-code; bit 6: fault row $56, no P-code
        LDAB    #$0C
        BRA     L3B8AC
L3B894:
        LDAB    #$0E
        BRSET   >SensorFaultFlags,Z,#$10,L3B8AC          ; bit 4: throttle sensor fault (ProcessThrottle, P0121 and the circuit codes)
        LDAB    #$0F
        BRSET   >FaultSet0B,Z,#$04,L3B8AC                ; bit 2: fault row $52, no P-code
        LDAB    #$08
        JSR     Nibble402Add
        BRA     L3B92A
L3B8AC:
        JSR     Nibble402Add
        CLRA
        BRCLR   >SwitchInputs2,Z,#$10,L3B8D8             ; bit 4: speed control switch (on/off, probably)
