;---------------------------------------------------------------------------------------------------
; PurgeMain ($3D800)
; Called from: MainLoop
;---------------------------------------------------------------------------------------------------
PurgeMain:
        BRSET   >PurgeFlags2,Z,#$20,L3D80A               ; bit 5: purge reset since the last start (PurgeReset; cleared at stall)
        JSR     PurgeReset
L3D80A:
        JSR     PurgeEnable
        JSR     PurgeCellCheck
        JSR     PurgeCellUpdateGate
        JSR     PurgeSolenoidCheck
        JSR     PurgeFlowMeasure
        JSR     PurgeRampCalc
        JSR     PurgeDutyOverride
        TSTA
        BNE     L3D858
        BCLR    >PurgeFlags,Z,#$80                       ; bit 7: purge vapour learn done for this cycle (PurgeVaporLearn); cleared by PurgeMain
        JSR     PurgeVaporLearn
        BRSET   >PurgeFlags,Z,#$80,L3D83C                ; bit 7: purge vapour learn done for this cycle (PurgeVaporLearn); cleared by PurgeMain
        JSR     PurgeRampControl
L3D83C:
        BRSET   >Options033B,#$20,L3D848                 ; bit 5: selects a branch in PurgeMain
        BRSET   >EgrMonFlags,Z,#$04,L3D85C               ; bit 2: EGR flow test phase running; EGR, closed loop and purge wait (EgrFlowMonitor)
L3D848:
        BRCLR   >Options0333,#$80,L3D854                 ; bit 7: EVAP purge solenoid fitted
        JSR     PurgeFlowControl
        BRA     L3D858
L3D854:
        JSR     PurgeDutySelect
L3D858:
        JSR     PurgePwmOutput
L3D85C:
        RTS

;---------------------------------------------------------------------------------------------------
; PurgeRampControl ($3D85E)
; Called from: PurgeMain
;---------------------------------------------------------------------------------------------------
PurgeRampControl:
        BRCLR   >Options0338,#$80,L3D870                 ; bit 7: purge variant (PurgeRampControl, PurgeVaporLearn)
        LDD     $0448,Z
        CPD     #$FFFF
        LBNE    L3DA36
L3D870:
        AIS     #$FFFA
        TSY
        LDAB    >ShortTermTrim1,Z
        LDAA    >O2AdaptValue1,Z
        JSR     FuelSysScaleMul
        TSTA
        BEQ     L3D888
        CLRB
L3D888:
        STAB    $00,Y
        LDAB    >ShortTermTrim2,Z
        LDAA    >O2AdaptValue2,Z
        JSR     FuelSysScaleMul
        TSTA
        BEQ     L3D89C
        CLRB
L3D89C:
        STAB    $01,Y
        BRCLR   >O2ActiveFlags,Z,#$08,L3D8B0             ; bit 3: as bit 7, but cleared when O2CheckEnable disables the sensor (SensorFaultFlags2 bit 3)
        BRCLR   >O2ActiveFlags,Z,#$04,L3D8C8             ; bit 2: as bit 6, cleared by SensorFaultFlags2 bit 2
        CMPB    $00,Y
        BCS     L3D8B6
        BRA     L3D8C8
L3D8B0:
        BRCLR   >O2ActiveFlags,Z,#$04,L3D8F8             ; bit 2: as bit 6, cleared by SensorFaultFlags2 bit 2
L3D8B6:
        STAB    >PurgeTrimLatched,Z
        LDAB    >O2Bank2Flags,Z
        STAB    $03,Y
        LDAB    >ShortTermTrim2,Z
        STAB    $02,Y
        BRA     L3D8DA
L3D8C8:
        LDAB    $00,Y
        STAB    >PurgeTrimLatched,Z
        LDAB    >O2Bank1Flags,Z
        STAB    $03,Y
        LDAB    >ShortTermTrim1,Z
        STAB    $02,Y
L3D8DA:
        BRSET   >PurgeFlags,Z,#$08,L3D8EE                ; bit 3: purge trim counted for the current cell (PurgeRampControl)
        BRCLR   $03,Y,#$08,L3D900
        BSET    >PurgeFlags,Z,#$08                       ; bit 3: purge trim counted for the current cell (PurgeRampControl)
        INC     >PurgeTrimCount,Z
        BRA     L3D900
L3D8EE:
        BRSET   $03,Y,#$08,L3D900
        BCLR    >PurgeFlags,Z,#$08                       ; bit 3: purge trim counted for the current cell (PurgeRampControl)
        BRA     L3D900
L3D8F8:
        CLRB
        STAB    >PurgeTrimLatched,Z
        STAB    $02,Y
L3D900:
        BRSET   >O2Bank1Flags,Z,#$20,L3DA34              ; bit 5: bank 1 closed-loop state read by the flex learning and trim averaging, byte writes only
        BRCLR   >Options032F,#$40,L3D912                 ; bit 6: upstream O2 sensor 2 fitted (second bank)
        BRSET   >O2Bank2Flags,Z,#$20,L3DA34
L3D912:
        JSR     PurgeVaporLoad
        TST     >PurgeLoad,Z
        BEQ     L3D924
        CLR     >PurgeRampStep,Z
        LBRA    L3DA34
L3D924:
        LDAA    >PurgeRamp,Z
        CMPA    >PurgeRampFull
        LBCC    L3D9EC
        CMPA    >PurgeRampMin
        LBCS    L3D9EC
        LDAA    >ManifoldVacuum,Z
        LBEQ    L3D9EC
        CMPA    >PurgeVacuumMin
        LBCS    L3D9EC
        LDAA    >MainLoopCounter,Z
        BNE     L3D95A
        LDAA    #$FF
        CMPA    >PurgeLearnTimer,Z
        BEQ     L3D95A
        INC     >PurgeLearnTimer,Z
L3D95A:
        LDAA    >PurgeLearnTimer,Z
        CMPA    >PurgeLearnTime
        LBCC    L3D9DE
        LDAA    >PurgeTrimCount,Z
        CMPA    >PurgeTrimCountMin
        LBCS    L3D9F0
L3D972:
        CLR     >PurgeTrimCount,Z
        LDAB    >PurgeRampStep,Z
        CMPB    >PurgeRampStepMax
        BCC     L3D9F0
        LDAA    >PurgeCommand,Z
        CMPA    #$FF
        BCS     L3D990
        LDAA    <Baro,Z
        CMPA    >PurgeBaroMax
        BHI     L3D9F0
L3D990:
        LDAA    $02,Y
        BPL     L3D99A
        CMPA    >PurgeTrimRichLimit
        BCS     L3D9F0
L3D99A:
        LDAA    >PurgeTrimLatched,Z
        BPL     L3D9A6
        CMPA    >PurgeTrimLatchedLimit
        BCS     L3D9F0
L3D9A6:
        LDAA    >PurgeStartRamp,Z
        BNE     L3D9F0
        BRSET   >ThrottleState,Z,#$80,L3D9B8             ; bit 7: throttle open: above the learned closed position plus a margin (hysteresis when set)
        LDAA    >PurgeRampOffIdle
        BEQ     L3D9F0
L3D9B8:
        LDAA    >PurgeLearnTimer,Z
        CMPA    >PurgeLearnTime
        BCC     L3D9C8
        ADDB    >PurgeRampStepUp
        BRA     L3D9CC
L3D9C8:
        ADDB    >PurgeRampStepUp2
L3D9CC:
        BCS     L3D9D4
        CMPB    >PurgeRampStepMax
        BCS     L3D9D8
L3D9D4:
        LDAB    >PurgeRampStepMax
L3D9D8:
        STAB    >PurgeRampStep,Z
        BRA     L3D9F0
L3D9DE:
        LDAA    >PurgeTrimCount,Z
        CMPA    >PurgeTrimCountMin2
        BCS     L3D9F0
        LBRA    L3D972
L3D9EC:
        CLR     >PurgeTrimCount,Z
L3D9F0:
        LDAA    $02,Y
        BPL     L3D9FA
        CMPA    >PurgeTrimRichLimit
        BCS     L3DA06
L3D9FA:
        LDAA    >PurgeTrimLatched,Z
        BPL     L3DA34
        CMPA    >PurgeTrimLatchedLimit2
        BCC     L3DA34
L3DA06:
        LDAA    >MainLoopCounter,Z
        ANDA    >PurgeLearnMask
        CMPA    >PurgeLearnMask
        BNE     L3DA34
        CLR     >PurgeTrimCount,Z
        TST     >PurgeRampStep,Z
        BEQ     L3DA34
        LDAB    >PurgeStartRamp,Z
        BNE     L3DA34
        BRSET   >ThrottleState,Z,#$80,L3DA30             ; bit 7: throttle open: above the learned closed position plus a margin (hysteresis when set)
        LDAB    >PurgeRampOffIdle
        BEQ     L3DA34
L3DA30:
        DEC     >PurgeRampStep,Z
L3DA34:
        AIS     #$06
L3DA36:
        LDAA    >PurgeLearnRate,Z
        LBNE    L3DBC2
        LDAA    >PurgeRamp,Z
        LDX     #PurgeCommandBase
        JSR     Lookup2D
        STAA    <Scratch0,Z
        BRCLR   >PurgeFlowTestFlags,Z,#$30,L3DAB2
        LDAA    >PurgeDutyTarget,Z
        LDAB    >PurgeFlowStep,Z
        BRSET   >PurgeFlowTestFlags,Z,#$10,L3DA9A
        CMPB    >PurgeFlowStepTime
        BCS     L3DAB6
        BRSET   >O2Bank1Flags,Z,#$08,L3DA78              ; bit 3: bank 1 state read by the purge ramp and vapour learning, byte writes only
        BRCLR   >Options032F,#$40,L3DAB6                 ; bit 6: upstream O2 sensor 2 fitted (second bank)
        BRCLR   >O2Bank2Flags,Z,#$08,L3DAB6
L3DA78:
        SUBA    >PurgeFlowDutyStepDown
        BCC     L3DA80
        CLRA
L3DA80:
        CMPA    <Scratch0,Z
        BHI     L3DAAE
        BCLR    >PurgeFlowTestFlags,Z,#$20
        LDAA    <Scratch0,Z
        TST     >PurgeFlowTestResult,Z
